"""Source for catalogue-v2.json (activities)."""


def act(image, summary_image, gallery, intro, paragraphs, experiences, included, excluded, notes):
    return {
        "image": image,
        "summary_image": summary_image,
        "gallery": [{"image": g, "alt": a} for g, a in gallery],
        "intro": intro,
        "description": "".join(f"<p>{p}</p>" for p in paragraphs),
        "experiences": [{"title": t, "body": b} for t, b in experiences],
        "included": included,
        "excluded": excluded,
        "important_notes": "\n".join(notes),
    }


